package store.cadera.cdrjobs.listener;
import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import store.cadera.cdrjobs.gui.JobsMenu;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;
public final class MenuListener implements Listener{private final JobsMenu menu;private final SkillService miner;private final FarmerService farmer;private final HunterService hunter;public MenuListener(JobsMenu m,SkillService mi,FarmerService f,HunterService h){menu=m;miner=mi;farmer=f;hunter=h;}@EventHandler public void onClick(InventoryClickEvent e){String t=e.getView().getTitle();if(!t.equals(JobsMenu.MAIN_TITLE)&&!t.equals(JobsMenu.MINER_TITLE)&&!t.equals(JobsMenu.TRIALS_TITLE)&&!t.equals(JobsMenu.FARMER_TITLE)&&!t.equals(JobsMenu.FARMER_TRIALS_TITLE)&&!t.equals(JobsMenu.HUNTER_TITLE)&&!t.equals(JobsMenu.HUNTER_TRIALS_TITLE))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;ItemStack c=e.getCurrentItem();if(c==null||!c.hasItemMeta())return;ItemMeta meta=c.getItemMeta();String a=meta.getPersistentDataContainer().get(menu.actionKey(),PersistentDataType.STRING);if(a==null)return;String id=meta.getPersistentDataContainer().get(menu.skillKey(),PersistentDataType.STRING);switch(a){case"open_miner","back_miner"->menu.openMiner(p);case"open_miner_trials"->menu.openTrials(p);case"open_farmer","back_farmer"->menu.openFarmer(p);case"open_farmer_trials"->menu.openFarmerTrials(p);case"open_hunter","back_hunter"->menu.openHunter(p);case"open_hunter_trials"->menu.openHunterTrials(p);case"back_main"->menu.openMain(p);case"upgrade_miner_skill"->{if(id!=null)try{miner.tryUpgrade(p,MinerSkill.valueOf(id));menu.openMiner(p);}catch(Exception ignored){}}case"upgrade_farmer_skill"->{if(id!=null)try{farmer.tryUpgrade(p,FarmerSkill.valueOf(id));menu.openFarmer(p);}catch(Exception ignored){}}case"upgrade_hunter_skill"->{if(id!=null)try{hunter.tryUpgrade(p,HunterSkill.valueOf(id));menu.openHunter(p);}catch(Exception ignored){}}}}}
